        ListNode ascHead = head;
        ListNode descHead = head.next;
        ListNode asc = ascHead;
        ListNode desc = descHead;
        while (desc != null && desc.next != null) {
            asc.next = desc.next;
            asc = asc.next;
            desc.next = asc.next;
            desc = desc.next;
        }
        asc.next = null;
        ListNode descSorted = reverse(descHead);
        return merge(ascHead, descSorted);
