        carry = 0
        for i in range(len(res)):
            total = res[i] + carry
            res[i] = total % 10
            carry = total // 10
        while len(res) > 1 and res[-1] == 0:
            res.pop()

        head = None
        for d in res:
            head = ListNode(d, head)
        return head

